24	    fn fmt(
25	        &self,
26	        comment: &SourceComment<CssLanguage>,
27	        f: &mut Formatter<Self::Context>,
28	    ) -> FormatResult<()> {
29	        if is_doc_comment(comment.piece()) {
30	            let mut source_offset = comment.piece().text_range().start();
31	
32	            let mut lines = comment.piece().text().lines();
33	
34	            // SAFETY: Safe, `is_doc_comment` only returns `true` for multiline comments
35	            let first_line = lines.next().unwrap();
36	            write!(f, [text(first_line.trim_end(), source_offset)])?;
37	
38	            source_offset += first_line.text_len();
39	
40	            // Indent the remaining lines by one space so that all `*` are aligned.
41	            write!(
42	                f,
43	                [align(
44	                    1,
45	                    &format_once(|f| {
46	                        for line in lines {
47	                            write!(f, [hard_line_break(), text(line.trim(), source_offset)])?;
48	
49	                            source_offset += line.text_len();
50	                        }
51	
52	                        Ok(())
53	                    })
54	                )]
55	            )
56	        } else {
57	            write!(f, [comment.piece().as_piece()])
58	        }
59	    }
