97	        &self,
98	        comment: DecoratedComment<Self::Language>,
99	    ) -> CommentPlacement<Self::Language> {
100	        match comment.text_position() {
101	            CommentTextPosition::EndOfLine => handle_function_comment(comment)
102	                .or_else(handle_declaration_name_comment)
103	                .or_else(handle_complex_selector_comment)
104	                .or_else(handle_global_suppression),
105	            CommentTextPosition::OwnLine => handle_function_comment(comment)
106	                .or_else(handle_declaration_name_comment)
107	                .or_else(handle_complex_selector_comment)
108	                .or_else(handle_global_suppression),
109	            CommentTextPosition::SameLine => handle_function_comment(comment)
110	                .or_else(handle_declaration_name_comment)
111	                .or_else(handle_complex_selector_comment)
112	                .or_else(handle_global_suppression),
113	        }
114	    }
