117	fn handle_declaration_name_comment(
118	    comment: DecoratedComment<CssLanguage>,
119	) -> CommentPlacement<CssLanguage> {
120	    match comment.preceding_node() {
121	        Some(following_node) if AnyCssDeclarationName::can_cast(following_node.kind()) => {
122	            if following_node
123	                .parent()
124	                .is_some_and(|p| p.kind() == CssSyntaxKind::CSS_GENERIC_COMPONENT_VALUE_LIST)
125	            {
126	                CommentPlacement::Default(comment)
127	            } else {
128	                CommentPlacement::leading(following_node.clone(), comment)
129	            }
130	        }
131	        _ => CommentPlacement::Default(comment),
132	    }
133	}
134	
135	fn handle_function_comment(
136	    comment: DecoratedComment<CssLanguage>,
137	) -> CommentPlacement<CssLanguage> {
138	    let (Some(preceding_node), Some(following_node)) =
139	        (comment.preceding_node(), comment.following_node())
140	    else {
141	        return CommentPlacement::Default(comment);
142	    };
143	
144	    let is_inside_function = CssFunction::can_cast(comment.enclosing_node().kind());
145	    let is_after_name = CssIdentifier::can_cast(preceding_node.kind());
146	    if is_inside_function && is_after_name {
147	        CommentPlacement::leading(following_node.clone(), comment)
148	    } else {
149	        CommentPlacement::Default(comment)
150	    }
151	}
152	
153	fn handle_complex_selector_comment(
154	    comment: DecoratedComment<CssLanguage>,
155	) -> CommentPlacement<CssLanguage> {
156	    if let Some(complex) = CssComplexSelector::cast_ref(comment.enclosing_node())
157	        && let Ok(right) = complex.right()
158	    {
159	        return CommentPlacement::leading(right.into_syntax(), comment);
160	    }
161	    CommentPlacement::Default(comment)
162	}
163	
164	fn handle_global_suppression(
165	    comment: DecoratedComment<CssLanguage>,
166	) -> CommentPlacement<CssLanguage> {
167	    let node = comment.enclosing_node();
168	
169	    if node.text_range_with_trivia().start() == TextSize::from(0) {
170	        let has_global_suppression = node.first_leading_trivia().is_some_and(|trivia| {
171	            trivia
172	                .pieces()
173	                .filter(|piece| piece.is_comments())
174	                .any(|piece| CssCommentStyle::is_global_suppression(piece.text()))
175	        });
176	        let root = node.ancestors().find_map(AnyCssRoot::cast);
177	        if let Some(root) = root
178	            && has_global_suppression
179	        {
180	            return CommentPlacement::leading(root.syntax().clone(), comment);
181	        }
182	    }
183	
184	    CommentPlacement::Default(comment)
